function getTubeIndex(e){if(!e)return-1;var m=e.match(/^tube-(\d+)$/);return m?parseInt(m[1],10):-1}
function findTopBallInTube(ctx,t){var b=ctx.queryEntitiesWithData({tag:'in-container-tube-'+t});if(0===b.length)return null;var r=b[0];for(var i=1;i<b.length;i++)b[i].position.y>r.position.y&&(r=b[i]);return r}
function getBallColor(b){for(var i=0;i<b.tags.length;i++)if(0===b.tags[i].indexOf('color-'))return parseInt(b.tags[i].substring(6),10);return-1}
function calculateDropPosition(ctx,t,s){var d=ctx.getEntityData('tube-'+t);if(!d)return null;var y=d.position.y-3+.18+.6+s*1.32;return{x:d.position.x,y:y}}
exports.onPickup=function(ctx,a){var tt=ctx.getTapTargetId(),ti=getTubeIndex(tt);if(ti<0)return void ctx.emit('pickup_cancelled');var c=ctx.getVariable('tube'+ti+'_count')||0;if(0===c)return void ctx.emit('pickup_cancelled');var tb=findTopBallInTube(ctx,ti);if(!tb)return void ctx.emit('pickup_cancelled');var bc=getBallColor(tb);ctx.setVariable('heldBallId',tb.id);ctx.setVariable('heldBallColor',bc);ctx.setVariable('sourceTubeIndex',ti);ctx.setVariable('tube'+ti+'_count',c-1);var rb=ctx.queryEntitiesWithData({tag:'in-container-tube-'+ti}).filter(function(e){return e.id!==tb.id});if(0<rb.length){for(var nt=rb[0],i=1;i<rb.length;i++)rb[i].position.y>nt.position.y&&(nt=rb[i]);ctx.setVariable('tube'+ti+'_topColor',getBallColor(nt))}else ctx.setVariable('tube'+ti+'_topColor',-1);ctx.addTag(tb.id,'held');ctx.removeTag(tb.id,'in-container-tube-'+ti);var td=ctx.getEntityData('tube-'+ti);if(td){var ly=td.position.y+5;ctx.animateEntity(tb.id,{x:td.position.x,y:ly,duration:.2,easing:'easeOutQuad'})}ctx.emit('ball_picked')};
exports.onDrop=function(ctx,a){var tt=ctx.getTapTargetId(),ti=getTubeIndex(tt),si=ctx.getVariable('sourceTubeIndex'),hbi=ctx.getVariable('heldBallId'),hbc=ctx.getVariable('heldBallColor');if(ti<0||si<0||!hbi)return void ctx.emit('pickup_cancelled');if(ti===si)return void cancelPickup(ctx);var tc=ctx.getVariable('tube'+ti+'_count')||0,ttc=ctx.getVariable('tube'+ti+'_topColor');if(tc>=4)return void showInvalidFeedback(ctx,hbi);if(0<tc&&ttc!==hbc)return void showInvalidFeedback(ctx,hbi);var dp=calculateDropPosition(ctx,tc,tc);if(!dp)return void cancelPickup(ctx);ctx.animateEntity(hbi,{x:dp.x,y:dp.y,duration:.2,easing:'easeOutQuad'});ctx.removeTag(hbi,'held');ctx.addTag(hbi,'in-container-tube-'+ti);ctx.setVariable('tube'+ti+'_count',tc+1);ctx.setVariable('tube'+ti+'_topColor',hbc);ctx.setVariable('heldBallId','');ctx.setVariable('sourceTubeIndex',-1);ctx.setVariable('heldBallColor',-1);var mc=ctx.getVariable('moveCount')||0;ctx.setVariable('moveCount',mc+1);ctx.emit('ball_dropped')};
exports.checkWin=function(ctx,a){for(var i=0;i<6;i++){var c=ctx.getVariable('tube'+i+'_count')||0;if(0===c)continue;if(4!==c)return;var b=ctx.queryEntitiesWithData({tag:'in-container-tube-'+i});if(0===b.length)return;var fc=getBallColor(b[0]);for(var j=1;j<b.length;j++)if(getBallColor(b[j])!==fc)return}ctx.setVariable('_winAtElapsed',ctx.elapsed+.3)};
function cancelPickup(ctx){var hbi=ctx.getVariable('heldBallId'),si=ctx.getVariable('sourceTubeIndex'),hbc=ctx.getVariable('heldBallColor');if(hbi&&0<=si){var c=ctx.getVariable('tube'+si+'_count')||0,rp=calculateDropPosition(ctx,si,c);if(rp)ctx.animateEntity(hbi,{x:rp.x,y:rp.y,duration:.2,easing:'easeOutQuad'});ctx.removeTag(hbi,'held');ctx.addTag(hbi,'in-container-tube-'+si);ctx.setVariable('tube'+si+'_count',c+1);ctx.setVariable('tube'+si+'_topColor',hbc)}ctx.setVariable('heldBallId','');ctx.setVariable('sourceTubeIndex',-1);ctx.setVariable('heldBallColor',-1);ctx.emit('pickup_cancelled')}
function showInvalidFeedback(ctx,id){ctx.addTag(id,'invalid')}
